<nav class="learning-category-bar" aria-label="Chuyên mục <?=e(lhc_scopes()[$tab])?>"><a href="<?=e(lhc_url($tab,'',$q,$gradeFilter))?>" class="<?=$selectedCategory===''?'active':''?>">Tất cả chuyên mục</a><?php foreach(lhc_categories($categoryStore,$tab)as$categoryKey=>$category):?><a href="<?=e(lhc_url($tab,$categoryKey,$q,$gradeFilter))?>" class="<?=$selectedCategory===$categoryKey?'active':''?>"><?=e($category['name'])?></a><?php endforeach;?><a href="<?=e(lhc_url($tab,'unassigned',$q,$gradeFilter))?>" class="<?=$selectedCategory==='unassigned'?'active':''?>">Chưa phân chuyên mục</a></nav>
<?php if($tab==='games'):?><form method="get" class="d-flex gap-2 mb-3"><input type="hidden" name="tab" value="games"><input type="hidden" name="category" value="<?=e($selectedCategory)?>"><input class="form-control" type="search" name="q" value="<?=e($q)?>" aria-label="Tìm tiện ích" placeholder="Tìm tiện ích trong các chuyên mục…"><button class="btn btn-primary">Tìm</button></form><?php if(!$gameVisibilityLoaded):?><div class="alert alert-warning" role="alert">Chưa tải được danh sách tiện ích. Vui lòng thử lại sau.</div><?php endif;?><?php endif;?>
<?php if(!$categoryShelves):?><div class="learning-category-empty">Không tìm thấy chuyên mục. Hãy chọn lại một chuyên mục ở trên.</div><?php endif;?>
<?php foreach($categoryShelves as$shelf):$allShelfItems=$shelf['items'];$previewLimit=$selectedCategory!==''||!lhc_categories($categoryStore,$tab)?count($allShelfItems):($tab==='games'?8:6);$shelfPreview=array_slice($allShelfItems,0,$previewLimit);?>
<section class="learning-category-shelf" data-learning-category="<?=e($shelf['id'])?>" aria-labelledby="category-title-<?=e($shelf['id'])?>"><header class="learning-category-shelf-header"><div><h3 id="category-title-<?=e($shelf['id'])?>"><i class="bi bi-folder2-open me-1" aria-hidden="true"></i> <?=e($shelf['name'])?> <span><?=count($allShelfItems)?></span></h3><?php if($shelf['description']!==''):?><p><?=e($shelf['description'])?></p><?php endif;?></div><?php if($selectedCategory===''):?><a href="<?=e(lhc_url($tab,$shelf['id'],$q,$gradeFilter))?>">Xem tất cả <i class="bi bi-arrow-right" aria-hidden="true"></i></a><?php else:?><a href="<?=e(lhc_url($tab,'',$q,$gradeFilter))?>">Tất cả chuyên mục</a><?php endif;?></header>
<?php if(!$allShelfItems):?><div class="learning-category-empty">Chưa có nội dung trong chuyên mục này.</div><?php elseif($tab==='games'):$games=$shelfPreview;require __DIR__.'/learning_game_cards.php';else:$list=$shelfPreview;require __DIR__.'/learning_resource_cards.php';endif;?>
<?php if(count($allShelfItems)>count($shelfPreview)):?><p class="small text-muted text-end mt-3 mb-0">Đang hiển thị <?=count($shelfPreview)?> / <?=count($allShelfItems)?> mục. Chọn “Xem tất cả” để xem đầy đủ.</p><?php endif;?></section>
<?php endforeach;?>
